#include <vector>
#include <omp.h>

/* Compute the prefix sum of the vector x into output.
   Use OpenMP to compute in parallel.
   Example:

   input: [1, 7, 4, 6, 6, 2]
   output: [1, 8, 12, 18, 24, 26]
*/
void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    int max_threads = 1;
#pragma omp parallel
    {
#pragma omp single
        max_threads = omp_get_num_threads();
    }

    std::vector<double> block_sums(max_threads, 0.0);

#pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        const std::size_t chunk = (n + static_cast<std::size_t>(nt) - 1) / static_cast<std::size_t>(nt);
        const std::size_t begin = static_cast<std::size_t>(tid) * chunk;
        const std::size_t end   = (begin + chunk < n) ? (begin + chunk) : n;

        double local_sum = 0.0;
        if (begin < end) {
            for (std::size_t i = begin; i < end; ++i) {
                local_sum += x[i];
                output[i] = local_sum;
            }
        }
        block_sums[tid] = local_sum;

#pragma omp barrier

        double offset = 0.0;
        for (int t = 0; t < tid; ++t) {
            offset += block_sums[t];
        }

        if (begin < end && offset != 0.0) {
            for (std::size_t i = begin; i < end; ++i) {
                output[i] += offset;
            }
        }
    }
}
